INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q109284488', 'Egyptian Invasion of Kerma', 'Between 1575 and 1550 BC, the Kerma Kingdom posed a major threat to Ancient Egypt. According to inscriptions from tomb of Egyptian governor Sobeknakht II at Nekheb, Kerma forces invaded deep into Egyptian territory during this period.', -1506, NULL, NULL, NULL, NULL, NULL, 'year', '1506 BCE', 26, 'https://en.wikipedia.org/wiki/Egyptian_Invasion_of_Kerma'),
  ('Q5452509', 'First battle of Dongola', 'The First Battle of Dongola took place in 642 between the Rashidun Caliphate and the Christian kingdom of Makuria. The Muslim expedition encountered strong Makurian resistance, particularly from Nubian archers, and subsequently withdrew from Nubia.', 642, NULL, NULL, NULL, NULL, NULL, 'year', '642', 45, 'https://en.wikipedia.org/wiki/First_battle_of_Dongola'),
  ('Q7443083', 'Second battle of Dongola', 'The second battle of Dongola or siege of Dongola was a military engagement between early Arab forces of the Rashidun Caliphate and the Nubian-Christian forces of the kingdom of Makuria in 652. The battle ended Muslim expansion into Nubia, establishing trade and a historic peace between the Muslim world and a Christian nation.', 652, NULL, NULL, NULL, NULL, NULL, 'year', '652', 50, 'https://en.wikipedia.org/wiki/Second_battle_of_Dongola'),
  ('Q110192510', 'Battle of Dongola', 'The Battle of Dongola (1276) was fought between the Mamluk Sultanate under Baybars and the Kingdom of Makuria. The Mamluks achieved a decisive victory, capturing the Makurian capital Dongola, forcing the king David of Makuria to flee and placing a puppet on the Makurian throne.', 1276, NULL, NULL, NULL, NULL, NULL, 'year', '1276', 34, 'https://en.wikipedia.org/wiki/Battle_of_Dongola_(1276)'),
  ('Q31944', 'Mahdist War', 'The Mahdist War (Arabic: الثورة المهدية, romanized: ath-Thawra al-Mahdiyya; 1881–1899) was fought between the Mahdist Sudanese, led by Muhammad Ahmad bin Abdullah, who had proclaimed himself the "Mahdi" of Islam (the "Guided One"), and the forces of the Khedivate of Egypt, initially, and later the forces of Britain. After four years, the Mahdist rebels overthrew the Ottoman-Egyptian administration with the fall of Khartoum and gained control over Sudan.', 1881, NULL, NULL, 1899, NULL, NULL, 'year', '1881–1899', 71, 'https://en.wikipedia.org/wiki/Mahdist_War'),
  ('Q478597', 'Battle of El Obeid', 'The Battle of Shaykan was fought between Egyptian forces under the command of Hicks Pasha and the forces of Muhammad Ahmad, the self-proclaimed Mahdi, in the woods of Shaykan near Kashgil near the town of El Obeid during 3–5 November 1883.', 1883, 11, 3, 1883, 11, 5, 'day', '3 November 1883 – 5 November 1883', 47, 'https://en.wikipedia.org/wiki/Battle_of_Shaykan'),
  ('Q604356', 'Battle of Tamai', 'The Battle of Tamai (or Tamanieh) took place on 13 March 1884 between a British force under Sir Gerald Graham and a Mahdist Sudanese army led by Osman Digna. Despite his earlier victory at El Teb, Graham realised that Osman Digna''s force was far from broken and that he still enjoyed support among the local population.', 1884, 3, 13, NULL, NULL, NULL, 'day', '13 March 1884', 37, 'https://en.wikipedia.org/wiki/Battle_of_Tamai'),
  ('Q815159', 'Siege of Khartoum', 'The siege of Khartoum (also known as the battle of Khartoum or fall of Khartoum) took place from 13 March 1884 to 26 January 1885. Sudanese Mahdist forces captured the city of Khartoum, Sudan, from its Egyptian garrison, thereby gaining control over the whole of Turco-Egyptian Sudan.', 1884, 3, 13, 1885, 1, 26, 'day', '13 March 1884 – 26 January 1885', 52, 'https://en.wikipedia.org/wiki/Siege_of_Khartoum'),
  ('Q1288821', 'Battle of Abu Klea', 'The Battle of Abu Klea, also known as the Battle of Abu Tulayh, took place between 16 and 18 January 1885, at Abu Klea, Sudan, between the British Desert Column and Mahdist forces encamped near Abu Klea. The Desert Column, a force of approximately 1,400 soldiers, started from Korti, Sudan on 30 December 1884; the Desert Column''s mission, in a joint effort titled the "Gordon Relief Expedition", was to march across the Bayuda Desert to the aid of General Charles George Gordon at Khartoum, Sudan, who was besieged there by Mahdist forces.', 1885, 1, 17, NULL, NULL, NULL, 'day', '17 January 1885', 51, 'https://en.wikipedia.org/wiki/Battle_of_Abu_Klea'),
  ('Q2890200', 'Battle of Tofrek', 'The Battle of Tofrek was fought on 22 March 1885 some 5 miles inland from the port of Suakin on the Red Sea coast of Sudan. A contingent of some 3,000 troops from the British and Indian "Suakin Field Force" led by Major General Sir John Carstairs McNeill (under the overall command of General Gerald Graham) was attacked by a Mahdist force under the leadership of Osman Digna.', 1885, 3, 22, NULL, NULL, NULL, 'day', '22 March 1885', 34, 'https://en.wikipedia.org/wiki/Battle_of_Tofrek'),
  ('Q4872453', 'Battle of Suakin', 'The Battle of Suakin (also known as the Battle of Gemaizah), occurred on 20 December 1888 during the Mahdist War, when General Francis Grenfell defeated a Mahdist (Often called Dervishes by Europeans), force near Suakin, a chief port of Sudan. The Mahdist force, under Osman Digna, had advanced on Suakin with an intention to invest it.', 1888, 12, 20, NULL, NULL, NULL, 'day', '20 December 1888', 34, 'https://en.wikipedia.org/wiki/Battle_of_Suakin'),
  ('Q1785947', 'Battle of Gallabat', 'The Battle of Gallabat, also known as the Battle of Metemma, was fought on 9–10 March 1889 during the Mahdist War between the Mahdist Sudanese and Ethiopian forces. It is a critical event in Ethiopian history because Nəgusä Nägäst (or Emperor) Yohannes IV was killed in this battle, and because it was the last major battle on the Ethiopian front of the Mahdist War.', 1889, 3, 9, 1889, 3, 10, 'day', '9 March 1889 – 10 March 1889', 45, 'https://en.wikipedia.org/wiki/Battle_of_Gallabat'),
  ('Q3636373', 'Battle of Kassala', 'The Battle of Kassala was fought on July 17, 1894, between Italian colonial troops and Mahdist Sudanese forces.', 1894, 7, 17, NULL, NULL, NULL, 'day', '17 July 1894', 39, 'https://en.wikipedia.org/wiki/Battle_of_Kassala'),
  ('Q1137302', 'Battle of Omdurman', 'The Battle of Omdurman, also known as the Battle of Karary, was fought during the Anglo-Egyptian conquest of Sudan between a British–Egyptian expeditionary force commanded by British Commander-in-Chief (sirdar) major general Horatio Herbert Kitchener and a Sudanese army of the Mahdist State, led by Abdallahi ibn Muhammad (the Khalifa), the successor to the self-proclaimed Mahdi, Muhammad Ahmad. The battle took place on 2 September 1898, at Kerreri, 11 kilometres (6.8 mi) north of Omdurman.', 1898, 9, 2, NULL, NULL, NULL, 'day', '2 September 1898', 64, 'https://en.wikipedia.org/wiki/Battle_of_Omdurman'),
  ('Q3687151', 'Capture of Kassala', 'Operations on the Northern front, East Africa, 1940 (the Sudan Campaign) in the Second World War, were conducted by the British in Sudan and the Armed Forces Command of Italian East Africa (Comando Forze Armate dell''Africa Orientale Italiana) in Eritrea and Ethiopia. On 1 June 1940, Amedeo, Duke of Aosta the Viceroy and Governor-General of the Africa Orientale Italiana (AOI, Italian East Africa), commander in chief of the Armed Forces Command of the Royal Italian Army (Regio Esercito) and General of the Air Force (Generale d''Armata Aerea), had about 290,476 local and metropolitan troops…', 1940, 6, 10, 1941, 1, 17, 'day', '10 June 1940 – 17 January 1941', 34, 'https://en.wikipedia.org/wiki/Northern_front%2C_East_Africa%2C_1940'),
  ('Q21515053', '1969 Sudanese coup d''état', 'The government of President Ismail al-Azhari and Prime Minister Muhammad Ahmad Mahgoub of Sudan was overthrown in a bloodless coup d''état on 25 May 1969. The coup ended Sudan''s second democratic era.', 1969, 5, 25, NULL, NULL, NULL, 'day', '25 May 1969', 39, 'https://en.wikipedia.org/wiki/1969_Sudanese_coup_d''%C3%A9tat'),
  ('Q4574675', '1971 Sudanese coup d''état', 'Major Hashem al-Atta led a coup d''état in Sudan on 19 July 1971 against the government of President Gaafar Nimeiry. While the coup was led by officers associated with the Sudanese Communist Party (SCP), the party''s central committee and its General Secretary, Abdel Khaliq Mahjub, had not given prior approval for the military action.', 1971, 7, 22, 1971, 7, 22, 'day', '22 July 1971', 34, 'https://en.wikipedia.org/wiki/1971_Sudanese_coup_d''%C3%A9tat'),
  ('Q82664', 'Iran–Iraq War', 'The Iran–Iraq War, also called the First Imposed War, Eight-Year War, or Sacred Defense by Iran, began with the Iraqi invasion of Iran in September 1980. After eight years of conflict, both countries accepted a ceasefire deal brokered by the United Nations, which became effective in August 1988.', 1980, 9, 22, 1988, 8, 20, 'day', '22 September 1980 – 20 August 1988', 86, 'https://en.wikipedia.org/wiki/Iran%E2%80%93Iraq_War'),
  ('Q842380', 'Second Sudanese Civil War', 'The Second Sudanese Civil War was a conflict from 1983 to 2005 between the central Sudanese government and the Sudan People''s Liberation Army. It was largely a continuation of the First Sudanese Civil War of 1955 to 1972.', 1983, 6, 5, 2005, 1, 9, 'day', '5 June 1983 – 9 January 2005', 69, 'https://en.wikipedia.org/wiki/Second_Sudanese_Civil_War'),
  ('Q138775728', '1988 Sudan famine', 'The 1988 famine in Bahr el Ghazal, Sudan, also called cok makurup was a large humanitarian disaster in Bahr el Ghazal which killed around 250,000 people. The famine was caused by looting, raiding, displacement, killing, and abduction of Dinka by government funded Arab Muraheleen.', 1988, NULL, NULL, NULL, NULL, NULL, 'year', '1988', 26, 'https://en.wikipedia.org/wiki/1988_Sudan_famine'),
  ('Q606081', '1989 Sudanese coup d''état', 'A bloodless coup d''état in Sudan overthrew the democratically elected government of Prime Minister Sadiq al-Mahdi and President Ahmed al-Mirghani on 30 June 1989, ending Sudan''s third democratic era. Carried out by a faction of the Sudanese Armed Forces heavily infiltrated and directed by the National Islamic Front (NIF), the coup was led by Brigadier General Omar al-Bashir and architected by Islamist ideologue Hassan al-Turabi, establishing a totalitarian military-religious regime that ruled the country for the next 30 years until its overthrow in 2019.', 1989, 6, 30, NULL, NULL, NULL, 'day', '30 June 1989', 43, 'https://en.wikipedia.org/wiki/1989_Sudanese_coup_d''%C3%A9tat'),
  ('Q39046853', '1993 Sudan famine', 'In 1993, a famine in Sudan occurred amidst political unrest and the then ongoing Second Sudanese Civil War.', 1993, NULL, NULL, NULL, NULL, NULL, 'year', '1993', 34, 'https://en.wikipedia.org/wiki/1993_Sudan_famine'),
  ('Q75756', 'Second Congo War', 'The Second Congo War, also known as Africa''s World War or the Great War of Africa, was a major conflict that began on 2 August 1998 in the Democratic Republic of the Congo (DRC), just over a year after the First Congo War. The war initially erupted when Congolese president Laurent-Désiré Kabila turned against his former allies from Rwanda and Uganda, who had helped him seize power.', 1998, 8, 2, 2003, 6, 30, 'day', '2 August 1998 – 30 June 2003', 75, 'https://en.wikipedia.org/wiki/Second_Congo_War'),
  ('Q4594006', '1998 Sudan famine', 'The famine in Sudan in 1998 was a humanitarian disaster caused mainly by the Second Sudanese Civil War, including attacks on civilians, mass displacement, the destruction and seizure of food resources, and restrictions on humanitarian aid, with drought linked to El Niño as a contributing factor. The worst affected area was Bahr el Ghazal in southwestern Sudan.', 1998, NULL, NULL, NULL, NULL, NULL, 'year', '1998', 34, 'https://en.wikipedia.org/wiki/1998_Sudan_famine'),
  ('Q190758', 'War in Darfur', 'The War in Darfur, also nicknamed the Land Cruiser War, was a major armed conflict in the Darfur region of Sudan that began in February 2003 when the Sudan Liberation Movement (SLM) and the Justice and Equality Movement (JEM) rebel groups began fighting against the government of Sudan, which they accused of oppressing Darfur''s non-Arab population. The government responded to attacks by carrying out a campaign of ethnic cleansing against Darfur''s non-Arabs.', 2003, 2, 26, 2020, 8, 31, 'day', '26 February 2003 – 31 August 2020', 77, 'https://en.wikipedia.org/wiki/War_in_Darfur'),
  ('Q42915906', 'Darfur genocide', 'The Darfur genocide was the systematic killing of ethnic Darfuri people during the War in Darfur. The genocide, which was carried out against the Fur, Masalit and Zaghawa ethnic groups, led the International Criminal Court (ICC) to indict several people for crimes against humanity, rape, forced transfer and torture.', 2003, 2, 23, 2008, NULL, NULL, 'day', '23 February 2003 – 2008', 48, 'https://en.wikipedia.org/wiki/Darfur_genocide_(2003%E2%80%932005)'),
  ('Q4609345', '2007 Sudan floods', 'On 3 July 2007, flash floods during Sudan''s rainy season devastated much of the country''s central, southern, and western regions. The Sudanese government referred to the floods as the "worst in living memory".', 2007, 7, 3, NULL, NULL, NULL, 'day', '3 July 2007', 34, 'https://en.wikipedia.org/wiki/2007_Sudan_floods'),
  ('Q2673524', 'Sudan Airways Flight 109', 'Sudan Airways Flight 109 was a scheduled international Amman–Damascus–Khartoum passenger flight, operated with an Airbus A310 by the flag carrier of Sudan, Sudan Airways. On 10 June 2008, at approximately 17:26 UTC, the Airbus A310 crashed on landing at Khartoum International Airport, killing 30 of the 214 occupants on board.', 2008, 6, 10, NULL, NULL, NULL, 'day', '10 June 2008', 53, 'https://en.wikipedia.org/wiki/Sudan_Airways_Flight_109'),
  ('Q2822718', '2012 Sudan Antonov An-26 crash', 'On 19 August 2012, an Antonov An-26 airplane of Alfa Airlines crashed near the town of Talodi, Sudan, killing all 32 occupants on board. The aircraft was carrying a Sudanese government delegation, and among the victims were members of the Sudanese government, several high-ranking members of the Sudanese Armed Forces and other officials, and a television crew.', 2012, 8, 19, NULL, NULL, NULL, 'day', '19 August 2012', 45, 'https://en.wikipedia.org/wiki/2012_Talodi_Antonov_An-26_crash'),
  ('Q16202932', '2013 Sudan floods', 'Continuous and heavy rains in much of Sudan, starting in early August 2013, resulted in flood damage in at least 14 of 18 Sudanese states. Over 300,000 people are reported to have been affected, with over 25,000 homes reported destroyed.', 2013, NULL, NULL, NULL, NULL, NULL, 'year', '2013', 39, 'https://en.wikipedia.org/wiki/2013_Sudan_floods'),
  ('Q60289711', 'Sudanese Revolution', 'The Sudanese revolution (Arabic: الثورة السودانية, romanised: al-Thawrah al-Sūdānīyah) was a major shift of political power in Sudan that started with street protests throughout Sudan on 19 December 2018 and continued with sustained civil disobedience for about eight months, during which the 2019 Sudanese coup d''état deposed President Omar al-Bashir on 11 April after thirty years in power. On 3 June, the Khartoum massacre took place under the leadership of the Transitional Military Council (TMC) that replaced al-Bashir, and in July and August 2019 the TMC and the Forces of Freedom and…', 2018, 12, 19, NULL, NULL, NULL, 'day', '19 December 2018', 58, 'https://en.wikipedia.org/wiki/Sudanese_revolution'),
  ('Q63096026', '2019 Sudanese coup d''état', 'A coup d''état overthrew President Omar al-Bashir and his three-decade authoritarian regime in Sudan on 11 April 2019, after months of widespread popular protests demanding his departure. Led by Defense Minister Lieutenant General Ahmed Awad Ibn Auf, the high command of the Sudanese Armed Forces dissolved the National Legislature, suspended the constitution, and declared a three-month state of emergency, before ultimately agreeing to a power-sharing arrangement with civilian forces that paved the way for a transitional government.', 2019, 4, 11, NULL, NULL, NULL, 'day', '11 April 2019', 60, 'https://en.wikipedia.org/wiki/2019_Sudanese_coup_d''%C3%A9tat'),
  ('Q64481622', 'Khartoum massacre', 'The Khartoum massacre occurred on 3 June 2019, when the armed forces of the Sudanese Transitional Military Council, headed by the Lieutenant-General Abdel Fattah Abdelrahman Burhan of the Sudanese Armed Forces (SAF) and his deputy, Mohamed Hamdan Dagalo of the Rapid Support Forces (RSF), the immediate successor organisation to the Janjaweed militia, used heavy gunfire and tear gas to disperse a sit-in by protestors in Khartoum, killing over 100 people. It has been difficult to assess the actual number killed.', 2019, 6, 3, NULL, NULL, NULL, 'day', '3 June 2019', 51, 'https://en.wikipedia.org/wiki/Khartoum_massacre'),
  ('Q65122495', 'Sudanese transition to democracy', 'A series of political agreements among Sudanese political and military forces for a democratic transition in Sudan began in July 2019. Omar al-Bashir overthrew the democratically elected government of Sadiq al-Mahdi in 1989 and was himself overthrown in the 2019 Sudanese coup d''état, in which he was replaced by the Transitional Military Council (TMC) after months of sustained street protests.', 2019, 7, 5, 2021, 10, 25, 'day', '5 July 2019 – 25 October 2021', 39, 'https://en.wikipedia.org/wiki/Sudanese_transition_to_democracy_(2019%E2%80%932021)'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q98929935', '2020 Sudan floods', 'In September 2020, profuse and continuous rainfall in Sudan caused a devastating flood across 17 out of the 18 states Sudanese states with the Blue Nile reaching water levels not seen for nearly a century. It ranks among the most severe floods recorded in the region.', 2020, NULL, NULL, NULL, NULL, NULL, 'year', '2020', 56, 'https://en.wikipedia.org/wiki/2020_Sudan_floods'),
  ('Q104856693', '2020 African Sahel floods', 'In all of 2020, flooding affected 2.7 million people in 18 countries in West and Central Africa and destroyed 197,000 houses, with many regions recording excess rainfalls. The number of flood-affected people this year was more than twice the case in 2019.', 2020, 8, NULL, 2020, 9, NULL, 'month', 'August 2020 – September 2020', 37, 'https://en.wikipedia.org/wiki/2020_African_Sahel_floods'),
  ('Q109229068', '2021 Sudanese coup d''état', 'On 25 October 2021, the Sudanese military, led by General Abdel Fattah al-Burhan, took control of the Government of Sudan in a military coup. At least five senior government figures were initially detained.', 2021, 10, 25, NULL, NULL, NULL, 'day', '25 October 2021', 65, 'https://en.wikipedia.org/wiki/2021_Sudanese_coup_d''%C3%A9tat'),
  ('Q113675134', '2022 Sudan floods', 'The 2022 Sudan floods saw the figure for flood-affected people in Sudan exceed the figure for 2021, rising to 314,500. From 2017 to 2021, there were 388,600 people affected by floods annually.', 2022, NULL, NULL, NULL, NULL, NULL, 'year', '2022', 37, 'https://en.wikipedia.org/wiki/2022_Sudan_floods'),
  ('Q123052433', 'Kreinik massacre', 'Beginning on April 21, 2022, clashes broke out between Janjaweed and Masalit civilians in the Kreinik refugee camp near El Geneina, West Darfur. These led to massacres over the following days by Janjaweed and the Rapid Support Forces, with hundreds of civilians killed.', 2022, 4, 21, 2022, 4, 25, 'day', '21 April 2022 – 25 April 2022', 34, 'https://en.wikipedia.org/wiki/Kreinik_massacre'),
  ('Q117716414', 'Sudanese civil war', 'Since April 2023, there has been a civil war in Sudan between the two main factions of the country''s military government. The conflict involves the internationally recognized government of Sudan led by the Sudanese Armed Forces (SAF), under General Abdel Fattah al-Burhan; against the rival Government of Peace and Unity led by the Rapid Support Forces (RSF) paramilitary group, commanded by General Hemedti (Muhammad Hamdan Dagalo Musa).', 2023, NULL, NULL, NULL, NULL, NULL, 'year', '2023', 80, 'https://en.wikipedia.org/wiki/Sudanese_civil_war_(2023%E2%80%93present)'),
  ('Q117747625', 'Battle of Khartoum', 'The Battle of Khartoum was a major strategic battle for control of Khartoum, the capital of Sudan, with fighting in and around the city between the paramilitary Rapid Support Forces (RSF), and the Sudanese Armed Forces (SAF), as part of the civil war. The battle began on 15 April 2023, after the RSF captured Khartoum International Airport, several military bases, and the presidential palace in an attempted coup d''état, starting an escalating series of clashes.', 2023, 4, 15, 2025, 3, 26, 'day', '15 April 2023 – 26 March 2025', 50, 'https://en.wikipedia.org/wiki/Battle_of_Khartoum_(2023%E2%80%932025)'),
  ('Q118083896', 'Battle of Geneina', 'The Geneina massacre, also the Battle of Geneina, was a series of major battles for control of Geneina, the capital of West Darfur in Sudan, between the paramilitary Rapid Support Forces (RSF) and allied militias against Masalit self-defense militias. The battles primarily lasted between April 24 and June 14, 2023, with major attacks and massacres by the RSF and allied militias on Masalit civilians in the city.', 2023, 4, 15, 2023, 6, 14, 'day', '15 April 2023 – 14 June 2023', 41, 'https://en.wikipedia.org/wiki/Battle_of_Geneina'),
  ('Q118151569', 'Battle of Merowe Airport', 'The battle of Merowe Airport happened in April 2023 during the Sudanese civil war. It involved fighting between the Rapid Support Forces (RSF) and Sudanese Armed Forces (SAF) for control of the city of Merowe and its airport, and began with the RSF taking over 200 Egyptian soldiers as prisoners of war.', 2023, 4, 15, 2023, 4, 21, 'day', '15 April 2023 – 21 April 2023', 39, 'https://en.wikipedia.org/wiki/Battle_of_Merowe_Airport'),
  ('Q118162520', 'Battle of Nyala', 'The Battle of Nyala was a battle for control of Nyala, the capital of South Darfur in Sudan, between the paramilitary Rapid Support Forces (RSF), and the Sudanese Armed Forces during the ongoing Darfur campaign. The first battle occurred between 15 and 20 April 2023, during which hundreds were reported dead.', 2023, 4, 15, 2023, 10, 26, 'day', '15 April 2023 – 26 October 2023', 41, 'https://en.wikipedia.org/wiki/Battle_of_Nyala'),
  ('Q118219527', 'Siege of El Fasher', 'The Siege of El Fasher was the 30-month siege of the Sudanese city of El Fasher, North Darfur by the Rapid Support Forces (RSF), as part of the Sudanese civil war. It was preceded by a series of battles for control between the RSF and the Sudanese Armed Forces (SAF), during which the city became the last stronghold of the SAF in Darfur.', 2023, 4, 13, 2025, 10, 26, 'day', '13 April 2023 – 26 October 2025', 43, 'https://en.wikipedia.org/wiki/Siege_of_El_Fasher'),
  ('Q120355325', 'Battle of Kadugli', 'The Siege of Kadugli is in Kadugli, South Kordofan State, Sudan, during the current Sudanese civil war. It involves two aligned rebel factions, the SPLM-N (al-Hilu faction) and the Rapid Support Forces, that are trying to capture the city from the Sudanese Armed Forces.', 2023, 6, 8, NULL, NULL, NULL, 'day', '8 June 2023', 34, 'https://en.wikipedia.org/wiki/Battle_of_Kadugli'),
  ('Q120355509', 'Battle of Kutum', 'The Battle of Kutum was a conflict during the War in Sudan which occurred in and around the town of Kutum in North Darfur. The Rapid Support Forces quickly overran the city, and carried out massacres in the city and the neighboring Kassab IDP camp.', 2023, 5, 30, 2023, 6, 4, 'day', '30 May 2023 – 4 June 2023', 37, 'https://en.wikipedia.org/wiki/Battle_of_Kutum'),
  ('Q122831253', 'Misterei massacre', 'Between May 27 and 28, 2023, armed Arab gunmen affiliated with the Rapid Support Forces attacked the West Darfur town of Misterei during the Battle of Geneina, killing 97 Masalit civilians after brief clashes with the Sudanese Alliance and Masalit self-defense groups, and destroying the town.', 2023, 5, 28, 2023, 5, 28, 'day', '28 May 2023', 37, 'https://en.wikipedia.org/wiki/Misterei_massacre'),
  ('Q123466017', 'Masalit genocide', 'The Masalit genocide is a series of ongoing persecutions and mass killings of the Masalit people in West Darfur carried out by the Rapid Support Forces (RSF) and its allies as part of the Darfur genocide. The genocide has been recognized by Genocide Watch, the government of the United States, American academic Eric Reeves, Governor of West Darfur Khamis Abakar, and The Economist.', 2023, 4, 24, NULL, NULL, NULL, 'day', '24 April 2023', 39, 'https://en.wikipedia.org/wiki/Masalit_genocide'),
  ('Q123469637', 'Ardamata massacre', 'On 8 November 2023, the Rapid Support Forces (RSF) and Janjaweed massacred between 800 and 2,000 in Ardamata, Geneina, West Darfur, Sudan – although estimates vary. The attack came after the Sudanese Armed Forces''s 15th Infantry Division camp retreated to Chad between during 6-8 November.', 2023, 11, 8, NULL, NULL, NULL, 'day', '8 November 2023', 39, 'https://en.wikipedia.org/wiki/Ardamata_massacre'),
  ('Q123915813', 'Battle of Wad Madani', 'The Battle of Wad Madani was a battle in the Sudanese civil war over the control of Wad Madani, the capital of Gezira State in east-central Sudan, between the Sudanese Armed Forces (SAF) and the Rapid Support Forces (RSF). The initial battle ended with the RSF capturing the town on 19 December 2023.', 2023, 12, 15, 2023, 12, 19, 'day', '15 December 2023 – 19 December 2023', 34, 'https://en.wikipedia.org/wiki/Battle_of_Wad_Madani'),
  ('Q126937295', '2024 Sudan famine', 'Throughout 2024, the population of Sudan suffered from severe malnutrition and famine conditions as a result of the Sudanese civil war beginning in 2023, primarily in Darfur, Kordofan, and neighboring refugee-taking nations such as Chad. On 1 August, the Global Famine Review Committee released a report officially declaring that it was possible that IPC Phase 5 famine conditions were ongoing in North Darfur near Al-Fashir and there was a high risk of similar conditions throughout internally displaced persons (IDP) camps.', 2023, 4, NULL, NULL, NULL, NULL, 'month', 'April 2023', 41, 'https://en.wikipedia.org/wiki/Famine_in_Sudan_(2024%E2%80%93present)'),
  ('Q136868651', 'Darfur genocide (2023–present)', 'The Darfur genocide, also known as the second Darfur genocide, is an ongoing series of persecutions and mass killings of non-Arabs in Darfur carried out by the Rapid Support Forces (RSF) and its allies during the Sudanese civil war. The genocide has been recognized by Genocide Watch, the government of the United States, and American academic Eric Reeves.', 2023, 4, 15, NULL, NULL, NULL, 'day', '15 April 2023', 37, 'https://en.wikipedia.org/wiki/Darfur_genocide_(2023%E2%80%93present)'),
  ('Q124485448', 'Siege of Babanusa', 'The siege of Babanusa was a siege of the Sudanese civil war. The siege started when fighting erupted between the Rapid Support Forces (RSF) and the Sudanese Armed Forces (SAF) on 22 January 2024 near Babanusa.', 2024, 1, 22, 2024, 2, 5, 'day', '22 January 2024 – 5 February 2024', 34, 'https://en.wikipedia.org/wiki/Siege_of_Babanusa'),
  ('Q126370903', 'Wad An Nora massacre', 'The Wad Al-Noora massacre started at around 05:00 (GMT+2) on 5 June 2024, when the Rapid Support Forces (RSF) attacked the village of Wad Al-Noora in Al-Jazira state twice, killing at least 100 civilians. The massacre followed after the RSF besieging and opening fire on the village.', 2024, 6, 5, NULL, NULL, NULL, 'day', '5 June 2024', 39, 'https://en.wikipedia.org/wiki/Wad_An_Nora_massacre'),
  ('Q129259515', 'Galgani massacre', 'The Galgani massacre refers to a mass killing of civilians in the central Sudanese village of Galgani by the Rapid Support Forces (RSF) on 15 August 2024, which killed at least 108 people, including at least 24 women and children.', 2024, 8, 15, NULL, NULL, NULL, 'day', '15 August 2024', 34, 'https://en.wikipedia.org/wiki/Galgani_massacre'),
  ('Q136673545', 'El Fasher massacre', 'A genocidal massacre in the city of El Fasher in western Sudan was carried out between 26 October and 4 November 2025. Tens of thousands of civilians were executed or murdered, spawning a prolonged refugee crisis.', 2025, 10, 26, NULL, NULL, NULL, 'day', '26 October 2025', 56, 'https://en.wikipedia.org/wiki/El_Fasher_massacre');
